// Applies stream events to some state via the `apply` callback.
// Event shape: { id: string, seq: number, type: string, payload?: any }
//
// Events are applied strictly in seq order starting from startSeq. Events that
// arrive early are buffered until every lower seq has been applied. Duplicate
// deliveries (same id already applied or buffered) and stale events (seq already
// applied, or seq already buffered) are ignored.

export class EventProcessor {
  /**
   * @param {(event: object) => void} apply
   * @param {{ startSeq?: number }} [opts]
   */
  constructor(apply, { startSeq = 1 } = {}) {
    this.apply = apply;
    this.startSeq = startSeq;
    this.lastSeq = startSeq - 1;
    this.appliedIds = new Set();
    this.buffer = new Map(); // seq -> event
    this.bufferedIds = new Set();
  }

  /** Number of events received but not yet applied. */
  get pendingCount() {
    return this.buffer.size;
  }

  /**
   * Handle one delivered event.
   * @returns {object[]} events applied as a result of this call, in order
   */
  process(event) {
    const applied = [];

    // Idempotency: already applied or already buffered by id.
    if (this.appliedIds.has(event.id) || this.bufferedIds.has(event.id)) {
      return applied;
    }
    // Stale: seq already applied, or another event with this seq is buffered.
    if (event.seq <= this.lastSeq || this.buffer.has(event.seq)) {
      return applied;
    }

    this.buffer.set(event.seq, event);
    this.bufferedIds.add(event.id);

    // Drain every consecutive event that is now ready.
    while (this.buffer.has(this.lastSeq + 1)) {
      const next = this.buffer.get(this.lastSeq + 1);
      this.apply(next);
      this.buffer.delete(next.seq);
      this.bufferedIds.delete(next.id);
      this.appliedIds.add(next.id);
      this.lastSeq = next.seq;
      applied.push(next);
    }

    return applied;
  }
}

