// Collects cleanup callbacks and runs them on close().
export class Scope {
  constructor() {
    this.callbacks = [];
    this.closed = false;
  }

  /** Register a cleanup callback (may be async). */
  defer(cb) {
    if (this.closed) throw new Error('scope already closed');
    this.callbacks.push(cb);
  }

  /**
   * Runs deferred callbacks in LIFO order. Every callback runs even if some throw.
   * Rejects with the error if exactly one failed, or an AggregateError (in throw order)
   * if several failed. Calling close() again is a no-op.
   */
  async close() {
    if (this.closed) return;
    this.closed = true;
    const pending = this.callbacks.splice(0).reverse();
    const errors = [];
    for (const cb of pending) {
      try {
        await cb();
      } catch (err) {
        errors.push(err);
      }
    }
    if (errors.length === 1) throw errors[0];
    if (errors.length > 1) throw new AggregateError(errors, 'multiple cleanup callbacks failed');
  }
}

